import { mkdir, readFile, unlink, writeFile } from "fs/promises";
import path from "path";

// Where photos and voice notes live.
//  - SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY set -> a PRIVATE Supabase Storage bucket
//  - otherwise                                     -> a folder on this computer (.data/media)
// Files are only ever read back by the server (and handed to signed-in staff), never by a link
// that works for the public. File names are random, generated by us, never typed by a user.

const BUCKET = process.env.SUPABASE_STORAGE_BUCKET || "civicos-media";

function remote(): { url: string; key: string } | null {
  const url = process.env.SUPABASE_URL?.replace(/\/$/, "");
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  return url && key ? { url, key } : null;
}

/**
 * Supabase has two kinds of server key. The newer "sb_secret_..." keys are not JWTs and must be
 * sent in the apikey header only; the older service_role JWT works in both headers.
 */
function authHeaders(key: string): Record<string, string> {
  return key.startsWith("sb_secret_") ? { apikey: key } : { Authorization: `Bearer ${key}`, apikey: key };
}

function localDir() {
  return path.join(process.env.DATA_DIR || path.join(process.cwd(), ".data"), "media");
}

/** Names we generate look like "web-ab12….jpg" or "1741047293666637.jpg". Anything else is refused. */
function safe(name: string): string {
  if (!/^[A-Za-z0-9_-]+\.[a-z0-9]{2,4}$/.test(name)) throw new Error("Unsafe file name.");
  return name;
}

export async function putFile(name: string, bytes: Buffer, mime: string): Promise<void> {
  safe(name);
  const r = remote();
  if (!r) {
    await mkdir(localDir(), { recursive: true });
    await writeFile(path.join(localDir(), name), bytes);
    return;
  }
  const res = await fetch(`${r.url}/storage/v1/object/${BUCKET}/${name}`, {
    method: "POST",
    headers: { ...authHeaders(r.key), "Content-Type": mime, "x-upsert": "true" },
    body: new Uint8Array(bytes),
  });
  if (!res.ok) throw new Error(`storage upload failed (${res.status})`);
}

export async function getFile(name: string): Promise<Buffer | null> {
  safe(name);
  const r = remote();
  if (!r) return readFile(path.join(localDir(), name)).catch(() => null);
  const res = await fetch(`${r.url}/storage/v1/object/${BUCKET}/${name}`, {
    headers: authHeaders(r.key),
  });
  if (!res.ok) return null;
  return Buffer.from(await res.arrayBuffer());
}

export async function deleteFile(name: string): Promise<void> {
  safe(name);
  const r = remote();
  if (!r) {
    await unlink(path.join(localDir(), name)).catch(() => undefined);
    return;
  }
  await fetch(`${r.url}/storage/v1/object/${BUCKET}/${name}`, {
    method: "DELETE",
    headers: authHeaders(r.key),
  }).catch(() => undefined);
}

/** Creates the private bucket if it does not exist yet (used by `npm run db:migrate`). */
export async function ensureBucket(): Promise<"created" | "exists" | "local"> {
  const r = remote();
  if (!r) return "local";
  const res = await fetch(`${r.url}/storage/v1/bucket`, {
    method: "POST",
    headers: { ...authHeaders(r.key), "Content-Type": "application/json" },
    body: JSON.stringify({ id: BUCKET, name: BUCKET, public: false, file_size_limit: 12 * 1024 * 1024 }),
  });
  if (res.ok) return "created";
  const body = (await res.json().catch(() => null)) as { error?: string; message?: string; statusCode?: string } | null;
  if (res.status === 409 || /already exists|Duplicate/i.test(JSON.stringify(body))) return "exists";
  throw new Error(`could not create bucket (${res.status}): ${body?.message ?? body?.error ?? "unknown"}`);
}
